class Component extends DCLogic {
  componentDidMount() {
    const root = this.root; if (!root) return;
    const input = root.querySelector('[data-filter]');
    const status = root.querySelector('[data-status]');
    const clear = root.querySelector('[data-clear]');
    const groups = Array.from(root.querySelectorAll('[data-group]'));
    const marks = Array.from(root.querySelectorAll('[data-mark]'));
    const rails = Array.from(root.querySelectorAll('[data-rail]'));
    const empty = root.querySelector('[data-empty]');
    const total = 44;
    const sync = (d) => { const m = d.querySelector('[data-mark]'); if (m) m.textContent = d.open ? '\u2212' : '+'; };
    root.querySelectorAll('details').forEach(d => { sync(d); d.addEventListener('toggle', () => sync(d)); });
    const apply = () => {
      const q = (input.value || '').trim().toLowerCase();
      let hits = 0;
      groups.forEach(g => {
        let gh = 0;
        g.querySelectorAll('[data-q]').forEach(d => {
          const match = !q || d.textContent.toLowerCase().includes(q);
          d.style.display = match ? '' : 'none';
          if (match) { gh++; hits++; }
          if (q) { d.open = match; } else { d.open = false; }
          sync(d);
        });
        g.style.display = gh ? '' : 'none';
      });
      rails.forEach(a => {
        const t = root.querySelector(a.getAttribute('href'));
        a.style.opacity = (t && t.style.display !== 'none') ? '1' : '0.35';
      });
      if (empty) empty.style.display = hits ? 'none' : '';
      if (clear) clear.style.display = q ? '' : 'none';
      status.textContent = q
        ? (hits === 0 ? 'No question matches \u201C' + input.value.trim() + '\u201D' : hits + (hits === 1 ? ' question matches' : ' questions match') + ' \u201C' + input.value.trim() + '\u201D')
        : 'Showing all ' + total + ' questions in 12 topics';
    };
    input.addEventListener('input', apply);
    if (clear) clear.addEventListener('click', () => { input.value = ''; apply(); input.focus(); });
    apply();
  }
  renderVals() { return { rootRef: (el) => { this.root = el; } }; }
}
